package runtime

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"

	"github.com/LeuJasYoh/PCL-DSH-Go/internal/config"
)

// instanceIDPattern matches the instance IDs generated by internal/store
// (i- + 12 hex) while still rejecting path separators and control characters.
var instanceIDPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$`)

// profileInstallHomeSegments is the <dataRoot>/cache sub-path used for the
// throw-away HOME of profile dependency installs.
const profileInstallHomeSegments = "pnpm-home"

// EntryPath returns the validated absolute CLI entry of an installed runtime
// (docs/M3_INTERFACES.md 5). It is the exported form of the internal executable
// validation used by BuildLaunchSpec and Entries.
func (s *Service) EntryPath(version string) (string, error) {
	return s.executable(version)
}

// ProfileInstallEnvironment prepares the working directory and environment for
// restoring one instance profile's dependencies with the bundled node/pnpm
// (docs/M3_INTERFACES.md 5, docs/DSH_INTEGRATION.md 8).
//
// The returned dir is the profile directory
// <instances>/<instanceID>/dsh-home/profiles/<profile> (created if missing);
// callers run node pnpm.cjs install ... with that working directory. The
// returned env is the DSH whitelist environment (blank base, registry/proxy,
// bundled node/pnpm on PATH) plus a throw-away HOME under
// <dataRoot>/cache/pnpm-home so dependency installation cannot pollute the
// manager's or the user's home directory.
func (s *Service) ProfileInstallEnvironment(dirs config.Dirs, instanceID, profile, registry, proxy string) (string, []string, error) {
	if dirs.DataRoot == "" || dirs.InstancesDir == "" {
		return "", nil, fmt.Errorf("缺少数据目录：DataRoot/InstancesDir 不能为空")
	}
	if !filepath.IsAbs(dirs.DataRoot) || !filepath.IsAbs(dirs.InstancesDir) {
		return "", nil, fmt.Errorf("数据目录必须是绝对路径")
	}
	if !instanceIDPattern.MatchString(instanceID) {
		return "", nil, fmt.Errorf("实例 ID 无效：%q", instanceID)
	}
	if !validProfileName(profile) || profile == "." || profile == ".." {
		return "", nil, fmt.Errorf("profile 名称无效：%q", profile)
	}
	if s.tools == nil || s.tools.NodePath == "" || s.tools.PnpmScript == "" {
		return "", nil, fmt.Errorf("未定位到内置 Node/pnpm 工具链")
	}
	baseRegistry, err := normalizeRegistry(registry)
	if err != nil {
		return "", nil, err
	}
	if err := validateProxy(proxy); err != nil {
		return "", nil, err
	}

	instanceDirectory := filepath.Join(dirs.InstancesDir, instanceID)
	dshHome := filepath.Join(instanceDirectory, "dsh-home")
	agentsHome := filepath.Join(instanceDirectory, "agents-home")
	profileDirectory := filepath.Join(dshHome, "profiles", profile)
	installHome := filepath.Join(dirs.DataRoot, "cache", profileInstallHomeSegments, instanceID, profile)
	shimsDirectory := filepath.Join(dirs.DataRoot, "tools", "shims")
	for _, directory := range []string{profileDirectory, installHome, shimsDirectory} {
		if err := os.MkdirAll(directory, 0o700); err != nil {
			return "", nil, fmt.Errorf("创建 profile 安装目录 %s 失败：%w", directory, err)
		}
	}

	environment, err := buildLaunchEnvironment(launchEnvOptions{
		DataRoot:       dirs.DataRoot,
		NodePath:       s.tools.NodePath,
		PnpmHome:       derivePnpmHome(s.tools.ToolRoot, dirs.DataRoot),
		ShimsDirectory: shimsDirectory,
		DSHHome:        dshHome,
		AgentsHome:     agentsHome,
		Registry:       baseRegistry,
		Proxy:          proxy,
		Home:           installHome,
		HostPath:       os.Getenv("PATH"),
	})
	if err != nil {
		return "", nil, fmt.Errorf("构建 profile 安装环境失败：%w", err)
	}
	return profileDirectory, environment, nil
}
